:root {
    --bg-main: #0a0a0b;
    --bg-surface: #131316;
    --bg-hover: #1f1f24;
    --text-primary: #f4f4f5;
    --text-secondary: #a1a1aa;
    --text-muted: #71717a;
    --border-color: #27272a;
    --accent: #e4e4e7;
    --deal-accent: #f87171;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg-main);
    color: var(--text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
    font-family: 'Playfair Display', serif;
    font-weight: 400;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover {
    color: var(--text-secondary);
}

button {
    font-family: 'Inter', sans-serif;
    cursor: pointer;
    border: none;
    background: none;
}

/* Layout */
.container {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 2rem;
}

.section {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.section-title {
    font-size: 2.5rem;
    letter-spacing: -0.02em;
}

.section-link {
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid var(--text-primary);
    padding-bottom: 0.25rem;
}

/* Header */
.header {
    position: sticky;
